{
  "tools": [
    {
      "name": "bridge_scatter_props",
      "title": "Native Scatter Props",
      "toolset": "bridge_helpers",
      "description": "Scatter model props with a repeatable seed, optional ground snapping, rotation, scaling and grouping. Requires stopped play mode. Uses the existing Bridge helper's scene and undo behaviour.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "model": {
            "type": "string",
            "description": "Project-relative model path, as returned by asset_search."
          },
          "center": {
            "type": "string",
            "description": "World-space centre as x,y,z, in Source units."
          },
          "radius": {
            "type": "number",
            "description": "Finite, nonnegative scatter radius in Source units.",
            "default": 256
          },
          "count": {
            "type": "integer",
            "description": "Number of props, from 1 to 300.",
            "default": 10
          },
          "seed": {
            "type": "integer",
            "description": "Nonnegative seed for repeatable placement.",
            "default": 1
          },
          "snapToGround": {
            "type": "boolean",
            "description": "Trace downward to place each prop on the ground.",
            "default": true
          },
          "randomYaw": {
            "type": "boolean",
            "description": "Randomise each prop's yaw.",
            "default": true
          },
          "scaleMin": {
            "type": "number",
            "description": "Positive minimum scale.",
            "default": 1
          },
          "scaleMax": {
            "type": "number",
            "description": "Maximum scale, at least scaleMin.",
            "default": 1
          },
          "group": {
            "type": "boolean",
            "description": "Parent the props under a new group object.",
            "default": true
          },
          "name": {
            "type": "string",
            "description": "Name prefix for the created objects.",
            "default": "Prop"
          }
        },
        "required": [
          "model",
          "center"
        ]
      }
    },
    {
      "name": "hammer_trace",
      "title": "Trace Ray",
      "toolset": "hammer",
      "description": "Trace a ray through the open map and report the first node it hits, where, and the surface normal - find the floor under a point, check what's in front of the camera, or probe where to place something. Traces Hammer's own geometry, so it works before the map is compiled.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "from": {
            "type": "string",
            "description": "Ray start as 'x,y,z'."
          },
          "to": {
            "type": "string",
            "description": "Ray end as 'x,y,z'."
          },
          "meshesOnly": {
            "type": "boolean",
            "description": "Only hit mesh geometry, ignoring entities and game objects.",
            "default": false
          },
          "skipToolsMaterials": {
            "type": "boolean",
            "description": "Don't hit tools materials like clip or trigger.",
            "default": false
          },
          "hitBackfaces": {
            "type": "boolean",
            "description": "Hit faces from behind too. A back face hit (the normal points along the ray) means the ray started inside something.",
            "default": false
          }
        },
        "required": [
          "from",
          "to"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Hit": {
            "type": "boolean"
          },
          "Position": {
            "type": "string"
          },
          "Normal": {
            "type": "string"
          },
          "Node": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "integer"
              },
              "Kind": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              },
              "ClassName": {
                "type": "string"
              },
              "Description": {
                "type": "string"
              },
              "Position": {
                "type": "string"
              },
              "Parent": {
                "type": "integer"
              },
              "GameObject": {
                "type": "string"
              },
              "Selected": {
                "type": "boolean"
              },
              "Visible": {
                "type": "boolean"
              }
            },
            "required": []
          }
        },
        "required": []
      }
    },
    {
      "name": "read_console",
      "title": "Read Console",
      "toolset": "instance",
      "description": "Read recent console output, oldest first - what the editor and game logged: prints, warnings, errors, exceptions, compile results. This is how you see the effect of what you just did. Errors come with the top of their stack trace. Every read ends with a cursor - pass it back as 'since' next time to get only what was logged after it, instead of re-reading the same output.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "limit": {
            "type": "integer",
            "description": "How many of the most recent matching entries to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 50
          },
          "minimumLevel": {
            "type": "string",
            "enum": [
              "Trace",
              "Info",
              "Warn",
              "Error"
            ],
            "description": "Lowest severity to include.",
            "default": "Trace"
          },
          "filter": {
            "type": "string",
            "description": "Only entries whose message or logger name contains this, case insensitive."
          },
          "since": {
            "type": "integer",
            "description": "Cursor from a previous read - only entries logged after it come back. 0 reads the most recent.",
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "scene_trace",
      "title": "Scene Trace",
      "toolset": "scene",
      "description": "Trace a ray through the active scene's physics and report what it hits - find the floor, check line of sight, probe where something can be placed.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "from": {
            "type": "string",
            "description": "Ray start as 'x,y,z'."
          },
          "to": {
            "type": "string",
            "description": "Ray end as 'x,y,z'."
          }
        },
        "required": [
          "from",
          "to"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Hit": {
            "type": "boolean",
            "description": "Whether the trace hit anything."
          },
          "StartedSolid": {
            "type": "boolean",
            "description": "Whether the trace started inside something solid."
          },
          "EndPosition": {
            "type": "string",
            "description": "Where the trace ended - the hit point, or the requested end on a miss."
          },
          "Normal": {
            "type": "string",
            "description": "The hit surface normal."
          },
          "Fraction": {
            "type": "number",
            "description": "How far along the ray the hit was, 0 to 1."
          },
          "Distance": {
            "type": "number",
            "description": "How far the trace travelled, in units."
          },
          "GameObject": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              }
            },
            "required": [],
            "description": "The game object hit. Null on a miss."
          },
          "Component": {
            "type": "string",
            "description": "The component type hit. Null on a miss."
          }
        },
        "required": []
      }
    }
  ],
  "total": 128
}
